"""Values and scalar conversion rules for the independently implemented VM."""
import math
import re

class Array:
    def __init__(self, values=None):
        self.data = {}
        self.next_index = 0
        self.cursor = 0
        if isinstance(values, dict):
            for k,v in values.items(): self.set(k,v)
        elif values is not None:
            for v in values: self.append(v)
    def set(self, key, value):
        key = array_key(key)
        self.data[key] = value
        if type(key) is int and key >= self.next_index:
            self.next_index = key+1
        return value
    def append(self, value):
        key = self.next_index
        self.next_index += 1
        self.data[key] = value
        return value
    def get(self,key,default=None): return self.data.get(array_key(key),default)
    def __len__(self): return len(self.data)
    def __iter__(self): return iter(self.data.values())
    def items(self): return self.data.items()
    def keys(self): return self.data.keys()
    def values(self): return self.data.values()
    def is_list(self): return list(self.data)==list(range(len(self.data)))
    def copy(self):
        a=Array()
        a.data={k:copy_value(v) for k,v in self.data.items()}
        a.next_index=self.next_index
        a.cursor=self.cursor
        return a
    def __repr__(self): return 'Array('+repr(self.data)+')'

class Object:
    def __init__(self,name='stdClass',props=None,oid=1):
        self.name=name
        self.props=props or {}
        self.oid=oid
        self.extra={}
    def __repr__(self): return self.name+' Object'

class Resource:
    def __init__(self, handle, name='stream', rid=5, uri='', mode='r'):
        self.handle=handle; self.name=name; self.rid=rid; self.uri=uri; self.mode=mode
        self.closed=False

class Cell:
    def __init__(self,value=None): self.value=value

class Ref:
    def __init__(self,getter,setter,deleter=None):
        self.getter=getter; self.setter=setter; self.deleter=deleter
    def get(self): return self.getter()
    def set(self,x): return self.setter(x)
    def delete(self):
        if self.deleter: self.deleter()

def deref(v): return v.value if isinstance(v,Cell) else v

def copy_value(v):
    if isinstance(v,Array): return v.copy()
    return v

def array_key(x):
    x=deref(x)
    if x is None: return ''
    if type(x) is bool: return int(x)
    if type(x) is float: return int(x) if math.isfinite(x) else 0
    if isinstance(x,Resource): return x.rid
    if isinstance(x,str) and re.fullmatch(r'(?:0|-?[1-9][0-9]*)',x):
        n=int(x)
        if -2**63<=n<2**63: return n
    return x

def truth(x):
    x=deref(x)
    if x is None or x is False: return False
    if isinstance(x,str): return x!='' and x!='0'
    if isinstance(x,Array): return len(x)>0
    if isinstance(x,(int,float)): return x!=0
    return True

def floatstr(x,precision=14,export=False,dump=False):
    if math.isnan(x): return 'NAN'
    if math.isinf(x): return '-INF' if x<0 else 'INF'
    if dump or precision<0:
        s=repr(x)
        if s.endswith('.0') and not export: s=s[:-2]
        # Zend uses scientific notation above 10^16 and below 10^-4.
        if abs(x)>=1e16 and 'e' not in s.lower(): s=format(x,'.16e')
    else: s=format(x,'.'+str(max(1,precision))+'g')
    if 'e' in s.lower():
        a,b=s.lower().split('e')
        if '.' in a: a=a.rstrip('0').rstrip('.')
        if '.' not in a: a+='.0'
        e=int(b)
        s=a+'E'+('+' if e>=0 else '-')+str(abs(e))
    elif export and '.' not in s: s+='.0'
    return s

def string(x,precision=14):
    x=deref(x)
    if x is None or x is False: return ''
    if x is True: return '1'
    if isinstance(x,str): return x
    if isinstance(x,int): return str(x)
    if isinstance(x,float): return floatstr(x,precision)
    if isinstance(x,Array): return 'Array'
    if isinstance(x,Resource): return 'Resource id #'+str(x.rid)
    if isinstance(x,Object): return x.name+' Object'
    return str(x)

num_pattern=re.compile(r'^[\t\n\r\v\f ]*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)')

def is_numeric(x):
    if type(x) in (int,float): return True
    return isinstance(x,str) and re.fullmatch(r'\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?\s*',x,re.ASCII) is not None

def number(x):
    x=deref(x)
    if x is None: return 0
    if type(x) in (int,float): return x
    if type(x) is bool: return int(x)
    if isinstance(x,str):
        m=num_pattern.match(x)
        if not m: return 0
        s=m.group(1)
        if '.' in s or 'e' in s.lower(): return float(s)
        n=int(s)
        return n if -2**63<=n<2**63 else float(n)
    if isinstance(x,Array): return 1 if x.data else 0
    if isinstance(x,Resource): return x.rid
    return 1

def integer(x):
    n=number(x)
    if isinstance(n,float):
        if not math.isfinite(n): return 0
        return ((int(n)+2**63)%(2**64))-2**63
    return n

def typename(x,debug=False):
    x=deref(x)
    if x is None: return 'null' if debug else 'NULL'
    if type(x) is bool: return 'bool' if debug else 'boolean'
    if type(x) is int: return 'int' if debug else 'integer'
    if type(x) is float: return 'float' if debug else 'double'
    if isinstance(x,str): return 'string'
    if isinstance(x,Array): return 'array'
    if isinstance(x,Resource): return 'resource (closed)' if x.closed else 'resource'
    if isinstance(x,Object): return x.name if debug else 'object'
    if hasattr(x,'params'): return 'Closure' if debug else 'object'
    return 'unknown type'

def same(a,b):
    a=deref(a); b=deref(b)
    if type(a) is not type(b): return False
    if isinstance(a,Array):
        return list(a.keys())==list(b.keys()) and all(same(v,b.get(k)) for k,v in a.items())
    if isinstance(a,Object): return a is b
    return a==b

def equal(a,b):
    a=deref(a); b=deref(b)
    if type(a) is bool or type(b) is bool: return truth(a)==truth(b)
    if a is None or b is None:
        if isinstance(a,str) or isinstance(b,str): return string(a)==string(b)
        return truth(a)==truth(b)
    if isinstance(a,Array) or isinstance(b,Array):
        if not isinstance(a,Array) or not isinstance(b,Array) or len(a)!=len(b): return False
        return all(k in b.data and equal(v,b.get(k)) for k,v in a.items())
    if isinstance(a,Object) or isinstance(b,Object):
        return isinstance(a,Object) and isinstance(b,Object) and a.name==b.name and equal(Array(a.props),Array(b.props))
    if type(a) in (int,float) and isinstance(b,str):
        return a==number(b) if is_numeric(b) else string(a)==b
    if type(b) in (int,float) and isinstance(a,str): return equal(b,a)
    if isinstance(a,str) and isinstance(b,str) and is_numeric(a) and is_numeric(b): return number(a)==number(b)
    return a==b

def compare(a,b):
    a=deref(a);b=deref(b)
    if equal(a,b): return 0
    if type(a) is bool or type(b) is bool or a is None or b is None:
        if (a is None and isinstance(b,str)) or (b is None and isinstance(a,str)):
            a=string(a);b=string(b)
        else: a=truth(a);b=truth(b)
    elif isinstance(a,Array) or isinstance(b,Array):
        if not isinstance(a,Array): return -1
        if not isinstance(b,Array): return 1
        if len(a)!=len(b): return 1 if len(a)>len(b) else -1
        for k,v in a.items():
            if k not in b.data: return 1
            c=compare(v,b.get(k))
            if c:return c
        return 0
    elif isinstance(a,Object) or isinstance(b,Object): return 1 if isinstance(a,Object) else -1
    elif is_numeric(a) and is_numeric(b): a=number(a);b=number(b)
    elif isinstance(a,str) or isinstance(b,str): a=string(a);b=string(b)
    try: return 1 if a>b else -1
    except Exception: return 1

def utf8len(s): return len(s.encode('utf-8','surrogateescape'))
def raw(s): return s.encode('utf-8','surrogateescape')
def text(b): return b.decode('utf-8','surrogateescape')

def from_python(v,objects=False,allocate=None):
    if isinstance(v,list): return Array(from_python(x,objects,allocate) for x in v)
    if isinstance(v,dict):
        if objects:
            o=allocate('stdClass') if allocate else Object()
            o.props={str(k):from_python(x,objects,allocate) for k,x in v.items()}
            return o
        return Array({k:from_python(x,objects,allocate) for k,x in v.items()})
    return v

def to_python(v,force_object=False):
    v=deref(v)
    if isinstance(v,Array):
        if v.is_list() and not force_object: return [to_python(x,force_object) for x in v]
        return {str(k):to_python(x,force_object) for k,x in v.items()}
    if isinstance(v,Object): return {str(k):to_python(x,force_object) for k,x in v.props.items()}
    return v

def dump(v,level=0):
    v=deref(v); ind='  '*level
    if v is None: return ind+'NULL\n'
    if type(v) is bool: return ind+'bool('+('true' if v else 'false')+')\n'
    if type(v) is int: return ind+'int('+str(v)+')\n'
    if type(v) is float: return ind+'float('+floatstr(v,dump=True)+')\n'
    if isinstance(v,str): return ind+'string('+str(utf8len(v))+') "'+v+'"\n'
    if isinstance(v,Resource): return ind+'resource('+str(v.rid)+') of type ('+('Unknown' if v.closed else v.name)+')\n'
    if isinstance(v,Array):
        s=ind+'array('+str(len(v))+') {\n'
        for k,x in v.items():
            s+=ind+'  ['+(('"'+k+'"') if isinstance(k,str) else str(k))+']=>\n'+dump(x,level+1)
        return s+ind+'}\n'
    if isinstance(v,Object):
        props=v.props
        s=ind+'object('+v.name+')#'+str(v.oid)+' ('+str(len(props))+') {\n'
        for k,x in props.items():
            key='"'+str(k)+'"'
            if k.startswith('\0'):
                parts=k.split('\0');key='"'+parts[2]+'":'+('protected' if parts[1]=='*' else '"'+parts[1]+'":private')
            s+=ind+'  ['+key+']=>\n'+dump(x,level+1)
        return s+ind+'}\n'
    return ind+'object(Closure)#1 (0) {\n}\n'

def print_r(v,level=0):
    v=deref(v)
    if not isinstance(v,(Array,Object)): return string(v)
    ind='    '*level
    name='Array' if isinstance(v,Array) else v.name+' Object'
    items=v.items() if isinstance(v,Array) else v.props.items()
    out=name+'\n'+ind+'(\n'
    for k,x in items:
        kk=str(k)
        if kk.startswith('\0'):
            a=kk.split('\0');kk=a[2]+(':'+('protected' if a[1]=='*' else a[1]+':private'))
        out+=ind+'    ['+kk+'] => '+print_r(x,level+2)+'\n'
    return out+ind+')\n'

def export(v,level=0):
    v=deref(v)
    if v is None: return 'NULL'
    if v is True:return 'true'
    if v is False:return 'false'
    if isinstance(v,str):
        if '\0' in v:return " . \"\\0\" . ".join(export(p,level) for p in v.split('\0'))
        return "'"+v.replace('\\','\\\\').replace("'","\\'")+"'"
    if isinstance(v,int):return str(v)
    if isinstance(v,float):return floatstr(v,precision=-1,export=True)
    if isinstance(v,Array):
        ind='  '*level
        out='array (\n'
        for k,x in v.items():
            out+=ind+'  '+export(k)+' => '
            if isinstance(x,Array): out+='\n'+ind+'  '
            out+=export(x,level+1)+',\n'
        return out+ind+')'
    if isinstance(v,Object):
        if v.name=='stdClass':
            s='(object) array(\n'
            for k,x in v.props.items():s+='  '*level+'   '+export(k)+' => '+export(x,level+1)+',\n'
            return s+'  '*level+')'
        return '\\'+v.name+'::__set_state('+export(Array(v.props),level)+')'
    return 'NULL'
PY"}

