class MT19937:
    def __init__(self,seed):
        self.state=[seed&0xffffffff]
        for i in range(1,624):self.state.append((1812433253*(self.state[-1]^(self.state[-1]>>30))+i)&0xffffffff)
        self.index=624
    def next(self):
        if self.index>=624:
            for i in range(624):
                x=(self.state[i]&0x80000000)|(self.state[(i+1)%624]&0x7fffffff)
                self.state[i]=self.state[(i+397)%624]^(x>>1)^(0x9908b0df if x&1 else 0)
            self.index=0
        y=self.state[self.index];self.index+=1;y^=y>>11;y^=(y<<7)&0x9d2c5680;y^=(y<<15)&0xefc60000;y^=y>>18
        return y&0xffffffff
    def randint(self,lo,hi):
        width=hi-lo
        if width<0:lo,hi=hi,lo;width=-width
        if width>=0xffffffff:
            if width==0xffffffff:return lo+self.next()
            x=self.next()|(self.next()<<32);return lo+x%(width+1)
        limit=0xffffffff-(0xffffffff%(width+1))-1
        x=self.next()
        while x>limit:x=self.next()
        return lo+x%(width+1)
